//! WAV audio inspection, validation, and assembly utilities.

use std::fs::File;
use std::io::{BufReader, Read, Seek, SeekFrom, Write};
use std::path::Path;

use super::errors::TtsError;
use super::models::WavAudioMetadata;

/// Inspects and strictly validates a WAV file generated by speech synthesis.
pub fn validate_wav_file(path: &Path) -> Result<WavAudioMetadata, TtsError> {
    if !path.exists() {
        return Err(TtsError::AudioValidationFailed(format!(
            "WAV file does not exist: {}",
            path.display()
        )));
    }

    let file = File::open(path)?;
    let file_len = file.metadata()?.len();
    if file_len < 44 {
        return Err(TtsError::AudioValidationFailed(format!(
            "WAV file too short ({} bytes, expected at least 44 bytes)",
            file_len
        )));
    }

    let mut reader = BufReader::new(file);
    let mut header = [0u8; 12];
    reader.read_exact(&mut header)?;

    // Check "RIFF" and "WAVE" markers
    if &header[0..4] != b"RIFF" || &header[8..12] != b"WAVE" {
        return Err(TtsError::AudioValidationFailed(
            "Invalid WAV header: missing RIFF/WAVE signature".into(),
        ));
    }

    let mut sample_rate: Option<u32> = None;
    let mut channel_count: Option<u16> = None;
    let mut bits_per_sample: Option<u16> = None;
    let mut data_len: Option<u32> = None;
    let mut data_offset: Option<u64> = None;

    // Scan chunks
    while let Ok(()) = reader.read_exact(&mut header[0..8]) {
        let chunk_id = &header[0..4];
        let chunk_size = u32::from_le_bytes([header[4], header[5], header[6], header[7]]);

        if chunk_id == b"fmt " {
            if chunk_size < 16 {
                return Err(TtsError::AudioValidationFailed(
                    "Malformed fmt chunk in WAV".into(),
                ));
            }
            let mut fmt_data = vec![0u8; chunk_size as usize];
            reader.read_exact(&mut fmt_data)?;

            let audio_format = u16::from_le_bytes([fmt_data[0], fmt_data[1]]);
            if audio_format != 1 {
                // Format 1 = PCM
                return Err(TtsError::AudioValidationFailed(format!(
                    "Unsupported non-PCM WAV format code: {audio_format}"
                )));
            }

            channel_count = Some(u16::from_le_bytes([fmt_data[2], fmt_data[3]]));
            sample_rate = Some(u32::from_le_bytes([
                fmt_data[4],
                fmt_data[5],
                fmt_data[6],
                fmt_data[7],
            ]));
            bits_per_sample = Some(u16::from_le_bytes([fmt_data[14], fmt_data[15]]));
        } else if chunk_id == b"data" {
            data_len = Some(chunk_size);
            data_offset = Some(reader.stream_position()?);
            // Seek past the data chunk
            reader.seek(SeekFrom::Current(chunk_size as i64))?;
        } else {
            // Skip unknown chunk
            reader.seek(SeekFrom::Current(chunk_size as i64))?;
        }
    }

    let sample_rate = sample_rate.ok_or_else(|| {
        TtsError::AudioValidationFailed("WAV file missing required 'fmt ' chunk".into())
    })?;
    let channel_count = channel_count
        .ok_or_else(|| TtsError::AudioValidationFailed("WAV file missing channel count".into()))?;
    let bits_per_sample = bits_per_sample.ok_or_else(|| {
        TtsError::AudioValidationFailed("WAV file missing bits per sample".into())
    })?;
    let data_len = data_len
        .ok_or_else(|| TtsError::AudioValidationFailed("WAV file missing 'data' chunk".into()))?;
    let data_offset = data_offset.ok_or_else(|| {
        TtsError::AudioValidationFailed("Could not determine WAV data chunk offset".into())
    })?;

    if data_len == 0 {
        return Err(TtsError::AudioValidationFailed(
            "WAV audio contains zero data bytes".into(),
        ));
    }

    let bytes_per_sample = (bits_per_sample as usize) / 8;
    let block_align = (channel_count as usize) * bytes_per_sample;
    if block_align == 0 {
        return Err(TtsError::AudioValidationFailed(
            "Invalid block align 0".into(),
        ));
    }

    let total_samples = (data_len as u64) / (block_align as u64);
    let duration_us = (total_samples as f64 / sample_rate as f64 * 1_000_000.0) as u64;

    // Check for silence / non-zero energy
    let mut file_for_data = File::open(path)?;
    file_for_data.seek(SeekFrom::Start(data_offset))?;
    let mut sample_buf = vec![0u8; (data_len as usize).min(65536)];
    let bytes_read = file_for_data.read(&mut sample_buf)?;

    let is_silent = sample_buf[..bytes_read].iter().all(|&b| b == 0);

    Ok(WavAudioMetadata {
        sample_rate,
        channel_count,
        bits_per_sample,
        sample_count: total_samples,
        duration_us,
        is_silent,
    })
}

/// Concatenates multiple sequential WAV files into a single compliant WAV file.
/// All input files must share identical sample rate, channel count, and bit depth.
pub fn concatenate_wav_files(
    inputs: &[impl AsRef<Path>],
    output: &Path,
) -> Result<WavAudioMetadata, TtsError> {
    if inputs.is_empty() {
        return Err(TtsError::AudioValidationFailed(
            "No input WAV files to concatenate".into(),
        ));
    }

    let first_meta = validate_wav_file(inputs[0].as_ref())?;
    let mut total_data_bytes: u64 = 0;
    let mut total_samples: u64 = 0;

    let mut temp_out = File::create(output)?;
    // Placeholder header (44 bytes), will rewrite at the end
    temp_out.write_all(&[0u8; 44])?;

    for input in inputs {
        let meta = validate_wav_file(input.as_ref())?;
        if meta.sample_rate != first_meta.sample_rate
            || meta.channel_count != first_meta.channel_count
            || meta.bits_per_sample != first_meta.bits_per_sample
        {
            return Err(TtsError::AudioValidationFailed(format!(
                "Cannot concatenate WAV files with mismatched audio formats (first: {}Hz {}ch, next: {}Hz {}ch)",
                first_meta.sample_rate, first_meta.channel_count, meta.sample_rate, meta.channel_count
            )));
        }

        // Copy data chunk bytes
        let mut file = File::open(input.as_ref())?;
        // Find data chunk
        let mut chunk_header = [0u8; 8];
        file.seek(SeekFrom::Start(12))?; // skip RIFF header

        while let Ok(()) = file.read_exact(&mut chunk_header) {
            let chunk_id = &chunk_header[0..4];
            let chunk_size = u32::from_le_bytes([
                chunk_header[4],
                chunk_header[5],
                chunk_header[6],
                chunk_header[7],
            ]);

            if chunk_id == b"data" {
                let mut buffer = vec![0u8; 65536];
                let mut remaining = chunk_size as usize;
                while remaining > 0 {
                    let to_read = remaining.min(buffer.len());
                    let read_bytes = file.read(&mut buffer[..to_read])?;
                    if read_bytes == 0 {
                        break;
                    }
                    temp_out.write_all(&buffer[..read_bytes])?;
                    total_data_bytes += read_bytes as u64;
                    remaining -= read_bytes;
                }
                break;
            } else {
                file.seek(SeekFrom::Current(chunk_size as i64))?;
            }
        }
        total_samples += meta.sample_count;
    }

    let bytes_per_sample = (first_meta.bits_per_sample / 8) as u32;
    let byte_rate = first_meta.sample_rate * (first_meta.channel_count as u32) * bytes_per_sample;
    let block_align = first_meta.channel_count * (bytes_per_sample as u16);
    let riff_size = (total_data_bytes + 36) as u32;

    // Write authoritative 44-byte WAV header
    temp_out.seek(SeekFrom::Start(0))?;
    temp_out.write_all(b"RIFF")?;
    temp_out.write_all(&riff_size.to_le_bytes())?;
    temp_out.write_all(b"WAVE")?;

    temp_out.write_all(b"fmt ")?;
    temp_out.write_all(&16u32.to_le_bytes())?; // fmt chunk size
    temp_out.write_all(&1u16.to_le_bytes())?; // PCM
    temp_out.write_all(&first_meta.channel_count.to_le_bytes())?;
    temp_out.write_all(&first_meta.sample_rate.to_le_bytes())?;
    temp_out.write_all(&byte_rate.to_le_bytes())?;
    temp_out.write_all(&block_align.to_le_bytes())?;
    temp_out.write_all(&first_meta.bits_per_sample.to_le_bytes())?;

    temp_out.write_all(b"data")?;
    temp_out.write_all(&(total_data_bytes as u32).to_le_bytes())?;
    temp_out.flush()?;

    let duration_us = (total_samples as f64 / first_meta.sample_rate as f64 * 1_000_000.0) as u64;

    Ok(WavAudioMetadata {
        sample_rate: first_meta.sample_rate,
        channel_count: first_meta.channel_count,
        bits_per_sample: first_meta.bits_per_sample,
        sample_count: total_samples,
        duration_us,
        is_silent: first_meta.is_silent,
    })
}
